func extractMCPJSONFrames(body []byte) []json.RawMessage {
	text := strings.TrimSpace(string(body))
	if !strings.Contains(text, "data:") {
		return []json.RawMessage{json.RawMessage(body)}
	}

	frames := make([]json.RawMessage, 0)
	var current strings.Builder
	for _, line := range strings.Split(text, "\n") {
		line = strings.TrimSpace(line)
		if line == "" {
			if strings.TrimSpace(current.String()) != "" {
				frames = append(frames, json.RawMessage(strings.TrimSpace(current.String())))
				current.Reset()
			}
			continue
		}
		if strings.HasPrefix(line, "data:") {
			data := strings.TrimSpace(strings.TrimPrefix(line, "data:"))
			if data == "" || data == "[DONE]" {
				continue
			}
			if current.Len() > 0 {
				current.WriteByte('\n')
			}
			current.WriteString(data)
		}
	}
	if strings.TrimSpace(current.String()) != "" {
		frames = append(frames, json.RawMessage(strings.TrimSpace(current.String())))
	}
	return frames
}

var (
	htmlTagPattern = regexp.MustCompile(`(?s)<[^>]*>`)
	hrefPattern    = regexp.MustCompile(`(?i)href=["']([^"']+)["']`)
)

func parseProductDocsText(text string) docsSearchResult {
	result := docsSearchResult{}
	rawText := truncate(strings.TrimSpace(text), maxProductDocsContentBytes)
	for _, line := range strings.Split(text, "\n") {
		key, value, ok := strings.Cut(line, ":")
		if !ok {
			continue
		}
		value = strings.TrimSpace(value)
		switch strings.ToLower(strings.TrimSpace(stripHTML(key))) {
		case "title":
			result.Title = truncate(cleanDocsText(value), maxProductDocsTitleBytes)
			if result.URL == "" {
				result.URL = truncate(extractHref(value), maxProductDocsURLBytes)
			}
		case "link":
			result.URL = truncate(cleanDocsText(value), maxProductDocsURLBytes)
		case "content":
			result.Content = truncate(cleanDocsText(value), maxProductDocsContentBytes)
		}
	}
	if result.Title == "" {
		result.Title = truncate(firstNonEmptyLine(rawText), maxProductDocsTitleBytes)
	}
	return result
}

func cleanDocsText(value string) string {
	return strings.TrimSpace(html.UnescapeString(stripHTML(value)))
}

func stripHTML(value string) string {
	return htmlTagPattern.ReplaceAllString(value, "")
}

func extractHref(value string) string {
	matches := hrefPattern.FindStringSubmatch(value)
	if len(matches) < 2 {
		return ""
	}
	return html.UnescapeString(strings.TrimSpace(matches[1]))
}

func firstNonEmptyLine(value string) string {
	for _, line := range strings.Split(value, "\n") {
		if cleaned := cleanDocsText(line); cleaned != "" {
			return cleaned
		}
	}
	return ""
}

